from itertools import combinations
n=7
edges=[]
for i in range(n):
    for j in range(i+1,n): edges.append((i,j))
idx={e:k for k,e in enumerate(edges)}
print(list(enumerate(edges)))
# brute force all 2^21 with partial 0-based find solution. Also try both partial bases.
def valid(bits):
    # no blue triangle (1)
    for tri in combinations(range(n),3):
        if all(bits[idx[tuple(sorted(e))]]==1 for e in combinations(tri,2)):
            return False
    for K in combinations(range(n),4):
        if all(bits[idx[tuple(sorted(e))]]==0 for e in combinations(K,2)):
            return False
    return True
partials0={3:0,7:0,12:0,18:0}
partials1={2:0,6:0,11:0,17:0}
partials_both={**partials0, **partials1}
for name, part in [('0base',partials0),('1base',partials1),('both',partials_both)]:
    sol=None
    count=0
    for x in range(1<<21):
        bits=[(x>>k)&1 for k in range(21)]
        if all(bits[k]==v for k,v in part.items()) and valid(bits):
            sol=bits; break
    print(name, sol)
    if sol: print('positions red fixed', [sol[k] for k in range(21)])
